using System.Collections.Generic;using Alterverse.AI;using Alterverse.Characters;using Alterverse.Combat;using Alterverse.Profile;using Alterverse.Shop;using Alterverse.UI;using UnityEngine;
namespace Alterverse.Match
{
public sealed class MatchScoreboard:MonoBehaviour
{
private sealed class Entry{public Health Health;public TeamMember Member;public string Name;public int Kills,Deaths,Assists;public int Score=>Kills*100+Assists*50-Deaths*15;}public static MatchScoreboard Instance{get;private set;}[SerializeField]private float refreshInterval=.5f,assistWindow=8f;private readonly Dictionary<Health,Entry> entries=new();private readonly Dictionary<Health,Dictionary<TeamMember,float>> damageCredit=new();private float nextRefresh;private HeroRespawn playerRespawn;private DimensionsFront front;private GUIStyle header,row,respawnStyle,frontStyle;private bool matchEnded,rewardGranted;private int winningTeam,matchReward,matchXp,playerKills,playerAssists,playerObjectives;
private void Awake(){if(Instance!=null&&Instance!=this){Destroy(gameObject);return;}Instance=this;}private void Start(){RefreshRoster();playerRespawn=Object.FindAnyObjectByType<HeroRespawn>();front=Object.FindAnyObjectByType<DimensionsFront>();if(front!=null)front.MatchEnded+=OnMatchEnded;}private void Update(){if(Time.unscaledTime>=nextRefresh){nextRefresh=Time.unscaledTime+refreshInterval;RefreshRoster();playerRespawn??=Object.FindAnyObjectByType<HeroRespawn>();if(front==null){front=Object.FindAnyObjectByType<DimensionsFront>();if(front!=null)front.MatchEnded+=OnMatchEnded;}}}
private static bool IsHero(TeamMember member)=>member!=null&&(member.GetComponent<HeroRespawn>()!=null||member.GetComponent<MobaBotRespawn>()!=null);public void RecordDamage(Health victim,GameObject source){if(victim==null||source==null)return;TeamMember attacker=source.GetComponentInParent<TeamMember>(),victimTeam=victim.GetComponent<TeamMember>();if(!IsHero(attacker)||!IsHero(victimTeam)||attacker==victimTeam||attacker.Team==victimTeam.Team)return;if(!damageCredit.TryGetValue(victim,out Dictionary<TeamMember,float> credits)){credits=new Dictionary<TeamMember,float>();damageCredit[victim]=credits;}credits[attacker]=Time.time;}
private void RefreshRoster(){foreach(TeamMember member in Object.FindObjectsByType<TeamMember>()){if(!IsHero(member))continue;Health health=member.GetComponent<Health>();if(health==null||entries.ContainsKey(health))continue;HeroIdentity identity=member.GetComponent<HeroIdentity>();string n=member.GetComponent<HeroRespawn>()!=null?PlayerProfile.PlayerName:(identity!=null?identity.DisplayName:DisplayName(member.gameObject.name));entries.Add(health,new Entry{Health=health,Member=member,Name=n});health.DiedWithSource+=OnHeroDied;}}private void OnHeroDied(Health victim,GameObject source){if(victim==null||!entries.TryGetValue(victim,out Entry victimEntry))return;victimEntry.Deaths++;TeamMember killer=source!=null?source.GetComponentInParent<TeamMember>():null;if(IsHero(killer)&&victimEntry.Member!=null&&killer.Team!=victimEntry.Member.Team){Entry killerEntry=FindEntry(killer);if(killerEntry!=null)killerEntry.Kills++;if(damageCredit.TryGetValue(victim,out Dictionary<TeamMember,float> credits))foreach(var credit in credits)if(IsHero(credit.Key)&&credit.Key!=killer&&Time.time-credit.Value<=assistWindow&&credit.Key.Team==killer.Team){Entry assist=FindEntry(credit.Key);if(assist!=null)assist.Assists++;}}damageCredit.Remove(victim);}private Entry FindEntry(TeamMember member){foreach(Entry e in entries.Values)if(e.Member==member)return e;return null;}private static string DisplayName(string raw)=>raw.Replace("AV_","").Replace("Bot_"," ");private int TeamKills(int team){int total=0;foreach(Entry e in entries.Values)if(e.Member!=null&&e.Member.Team==team)total+=e.Kills;return total;}private void OnMatchEnded(int team){winningTeam=team;matchEnded=true;if(!rewardGranted){TeamMember player=playerRespawn!=null?playerRespawn.GetComponent<TeamMember>():null;bool won=player!=null&&player.Team==team;Entry playerEntry=player!=null?FindEntry(player):null;playerKills=playerEntry?.Kills??0;playerAssists=playerEntry?.Assists??0;MatchTelemetry.HeroStats telemetry=playerEntry!=null?MatchTelemetry.Instance?.GetStats(playerEntry.Health):null;playerObjectives=telemetry!=null?Mathf.FloorToInt(telemetry.FrontContribution/2.5f):0;MatchRewardResult reward=MatchRewardService.GrantMatchReward(won,playerKills,playerAssists,playerObjectives);matchReward=reward.Shards;matchXp=reward.Xp;rewardGranted=true;}Time.timeScale=0;}
private float Performance(Entry e){MatchTelemetry.HeroStats s=MatchTelemetry.Instance?.GetStats(e.Health);return s!=null?s.MvpScore:e.Score;}private Entry Mvp(){Entry best=null;float bestScore=float.MinValue;foreach(Entry e in entries.Values){float score=Performance(e);if(best==null||score>bestScore){best=e;bestScore=score;}}return best;}
private void OnGUI(){header??=new GUIStyle(GUI.skin.label){fontSize=17,fontStyle=FontStyle.Bold,alignment=TextAnchor.MiddleCenter};row??=new GUIStyle(GUI.skin.label){fontSize=15,alignment=TextAnchor.MiddleCenter};respawnStyle??=new GUIStyle(GUI.skin.button){fontSize=22,fontStyle=FontStyle.Bold};frontStyle??=new GUIStyle(GUI.skin.label){fontSize=14,fontStyle=FontStyle.Bold,alignment=TextAnchor.MiddleCenter};if(matchEnded){DrawResult();return;}float compactWidth=Mathf.Min(330,Screen.width*.44f),compactX=(Screen.width-compactWidth)*.5f;GUI.Box(new Rect(compactX,42,compactWidth,48),GUIContent.none);GUI.Label(new Rect(compactX,43,compactWidth,23),$"ZERO  {TeamKills(0)}   •   {TeamKills(1)}  LUMEN",header);if(front!=null)GUI.Label(new Rect(compactX,65,compactWidth,20),$"FRONT  {front.ZeroControl:0}%  ◀  ▶  {front.LumenControl:0}%",frontStyle);if(playerRespawn==null||!playerRespawn.IsRespawning)return;float width=Mathf.Min(680,Screen.width*.82f),x=(Screen.width-width)*.5f,y=Mathf.Max(90,Screen.height*.15f);List<Entry> zero=new List<Entry>(),lumen=new List<Entry>();foreach(Entry e in entries.Values)(e.Member.Team==0?zero:lumen).Add(e);zero.Sort((a,b)=>Performance(b).CompareTo(Performance(a)));lumen.Sort((a,b)=>Performance(b).CompareTo(Performance(a)));float boardHeight=82+Mathf.Max(zero.Count,lumen.Count)*27;GUI.Box(new Rect(x,y,width,boardHeight+82),GUIContent.none);GUI.Label(new Rect(x,y+5,width,25),"DIMENSIONS FRONT  •  K / D / A / SCORE",header);if(front!=null)GUI.Label(new Rect(x,y+30,width,22),$"REALITY FRONT   ZERO {front.ZeroControl:0.0}%   |   LUMEN {front.LumenControl:0.0}%",frontStyle);DrawTeam(zero,x+10,y+57,width*.5f-15,"ZERO");DrawTeam(lumen,x+width*.5f+5,y+57,width*.5f-15,"LUMEN");Rect action=new Rect(x+width*.25f,y+boardHeight+18,width*.5f,48);if(playerRespawn.RespawnReady){if(GUI.Button(action,"RESPAWN",respawnStyle))playerRespawn.ConfirmRespawn();}else GUI.Label(action,$"RESPAWN IN  {Mathf.CeilToInt(playerRespawn.RemainingSeconds)}",header);}
private void DrawResult(){Entry mvp=Mvp();float w=Mathf.Min(620,Screen.width*.82f),h=Mathf.Min(455,Screen.height*.82f),x=(Screen.width-w)*.5f,y=(Screen.height-h)*.5f;GUI.Box(new Rect(x,y,w,h),GUIContent.none);GUI.Label(new Rect(x+20,y+18,w-40,42),winningTeam==0?"ZERO VICTORY":"LUMEN VICTORY",respawnStyle);GUI.Label(new Rect(x+20,y+65,w-40,26),$"MATCH XP  +{matchXp}   •   {(matchReward>0?$"SHARD DROP  ◆ {matchReward}": "NO SHARD DROP")}   •   BALANCE {PlayerWallet.Balance}",frontStyle);GUI.Label(new Rect(x+20,y+90,w-40,22),$"ACCOUNT LEVEL {PlayerExperience.Level}   •   {PlayerExperience.XpToNextLevel} XP TO NEXT",frontStyle);GUI.Label(new Rect(x+20,y+108,w-40,20),$"XP BASIS  •  {playerKills} KILLS  •  {playerAssists} ASSISTS  •  {playerObjectives} OBJECTIVES",frontStyle);GUI.Label(new Rect(x+20,y+130,w-40,32),"MATCH MVP",header);if(mvp!=null){HeroIdentity hero=mvp.Member.GetComponent<HeroIdentity>();bool player=mvp.Member.GetComponent<HeroRespawn>()!=null;MatchTelemetry.HeroStats s=MatchTelemetry.Instance?.GetStats(mvp.Health);GUI.Label(new Rect(x+20,y+164,w-40,42),mvp.Name,respawnStyle);GUI.Label(new Rect(x+20,y+206,w-40,24),player&&FounderEntitlement.Owned?"◆ FIRST TRAVELER ◆":"",frontStyle);GUI.Label(new Rect(x+20,y+234,w-40,30),$"{(hero!=null?hero.DisplayName:"HERO")}   •   {mvp.Kills} K / {mvp.Deaths} D / {mvp.Assists} A",header);string detail=s!=null?$"DMG {s.DamageDealt:0}   •   HEAL {s.Healing:0}   •   FRONT {s.FrontContribution:0.0}":"DIMENSIONS FRONT COMBATANT";GUI.Label(new Rect(x+20,y+272,w-40,28),detail,frontStyle);if(player)GUI.Label(new Rect(x+20,y+306,w-40,26),FounderEntitlement.Owned?$"ORIGIN SCAR  •  AVATAR {PlayerProfile.Avatar+1}":$"AVATAR {PlayerProfile.Avatar+1}",frontStyle);}if(GUI.Button(new Rect(x+w*.25f,y+h-68,w*.5f,46),"BACK TO FRONT",respawnStyle)){matchEnded=false;MainMenuController.ShowHome();}}
private void DrawTeam(List<Entry> team,float x,float y,float width,string title){GUI.Label(new Rect(x,y,width,22),title,header);for(int i=0;i<team.Count;i++){Entry e=team[i];bool founder=e.Member.GetComponent<HeroRespawn>()!=null&&FounderEntitlement.Owned;string badge=founder?"◆ ":"";GUI.Label(new Rect(x,y+24+i*27,width,24),$"{badge}{e.Name,-13}   {e.Kills} / {e.Deaths} / {e.Assists} / {Performance(e):0}",row);}}private void OnDestroy(){foreach(var pair in entries)if(pair.Key!=null)pair.Key.DiedWithSource-=OnHeroDied;if(front!=null)front.MatchEnded-=OnMatchEnded;entries.Clear();if(Instance==this)Instance=null;}
}
}